insert into public.post_translations (post_id, locale, title, slug, excerpt, content)
select id, 'es'::public.app_locale, $t$Propinas y horas extra: cómo funcionan las nuevas deducciones$t$, $t$prueba-propinas-y-horas-extra$t$, $t$Hasta $25,000 en propinas y hasta $12,500 de la parte adicional de tus horas extra. Quién califica y qué necesitas para reclamarlas.$t$, $t$<p><em>Publicación de prueba: revisa y edita este contenido antes de usarlo.</em></p><h2>Qué cambió</h2><p>La nueva ley permite deducir parte de las propinas y del pago adicional por horas extra en la declaración federal, para los años 2025 a 2028.</p><h2>Qué necesitas</h2><ul><li>Tu W-2 o 1099 con las propinas reportadas.</li><li>Los registros de tus horas extra.</li></ul><p>Tráelos a tu cita y revisamos si calificas.</p>$t$ from new_post
union all
select id, 'en'::public.app_locale, $t$Tips and overtime: how the new deductions work$t$, $t$test-tips-and-overtime$t$, $t$Up to $25,000 in tips and up to $12,500 of the extra part of your overtime pay. Who qualifies and what you need to claim them.$t$, $t$<p><em>Test post: review and edit this content before using it.</em></p><h2>What changed</h2><p>The new law lets you deduct part of your tips and of your overtime premium on your federal return, for tax years 2025 through 2028.</p><h2>What you need</h2><ul><li>Your W-2 or 1099 showing reported tips.</li><li>Your overtime records.</li></ul><p>Bring them to your appointment and we'll check whether you qualify.</p>$t$ from new_post;

