select id, 'es'::public.app_locale, $t$Ya abrimos citas para la temporada de impuestos$t$, $t$prueba-citas-temporada$t$, $t$Reserva tu cita desde ahora y llega a la temporada con tus papeles listos.$t$, $t$<p><em>Publicación de prueba: revisa y edita este contenido antes de usarlo.</em></p><p>Desde hoy puedes agendar tu cita para la próxima temporada de impuestos. Si subes tus documentos a Mi Archivo antes de venir, la cita es más rápida.</p>$t$ from new_post
union all
select id, 'en'::public.app_locale, $t$Appointments for tax season are now open$t$, $t$test-season-appointments$t$, $t$Book your appointment now and start tax season with your paperwork ready.$t$, $t$<p><em>Test post: review and edit this content before using it.</em></p><p>Starting today you can book your appointment for the upcoming tax season. If you upload your documents to My Files before coming in, the appointment goes faster.</p>$t$ from new_post;

