select id, 'es'::public.app_locale, $t$Tu reembolso, ahora por depósito directo$t$, $t$prueba-deposito-directo$t$, $t$El IRS está dejando los cheques en papel. Qué datos bancarios necesitas para recibir tu reembolso.$t$, $t$<p><em>Publicación de prueba: revisa y edita este contenido antes de usarlo.</em></p><p>El depósito directo es la forma más rápida de recibir tu reembolso. Necesitarás tu número de ruta y tu número de cuenta.</p><blockquote>Revisa bien los números: un error puede retrasar tu reembolso varias semanas.</blockquote>$t$ from new_post
union all
select id, 'en'::public.app_locale, $t$Your refund, now by direct deposit$t$, $t$test-direct-deposit$t$, $t$The IRS is phasing out paper checks. The bank details you need to get your refund.$t$, $t$<p><em>Test post: review and edit this content before using it.</em></p><p>Direct deposit is the fastest way to get your refund. You'll need your routing number and your account number.</p><blockquote>Double-check the numbers: a mistake can delay your refund by several weeks.</blockquote>$t$ from new_post;

