select id, 'en'::public.app_locale, $t$What to bring to your tax appointment: the full list$t$, $t$test-what-to-bring$t$, $t$ID, W-2, 1099, last year's return and bank details. Everything you need in one list.$t$, $t$<p><em>Test post: review and edit this content before using it.</em></p><ul><li>Photo ID.</li><li>Social Security number or ITIN for each person.</li><li>W-2, 1099 and 1095-A.</li><li>Last year's tax return.</li><li>Routing and account number for direct deposit.</li></ul>$t$ from new_post;

