select id, 'en'::public.app_locale, $t$New York sales tax: the basics for your business$t$, $t$test-ny-sales-tax$t$, $t$Who needs to register, how much to charge and how often to file.$t$, $t$<p><em>Test post: review and edit this content before using it.</em></p><p>If you sell goods or certain services in New York, you must register to collect sales tax. The rate combines the state and local rates, so it varies by county.</p>$t$ from new_post;

