select id, 'en'::public.app_locale, $t$Estimated taxes: the four dates you can't forget$t$, $t$test-estimated-taxes$t$, $t$April 15, June 15, September 15 and January 15. What to pay on each one.$t$, $t$<p><em>Test post: review and edit this content before using it.</em></p><p>If you're self-employed, the IRS expects payments during the year. The usual dates are April 15, June 15, September 15 and January 15 of the following year.</p>$t$ from new_post;

